const fs = require('fs');
const path = require('path');

const KEY = 'c7c285b9c599f3b1963b2f053a1bf93b';

async function main() {
    try {
        // Step 1: 获取杭州电子科技大学的坐标
        console.log('📍 正在获取杭州电子科技大学坐标...');
        const geoRes = await axios.get('https://restapi.amap.com/v3/geocode/geo', {
            params: {
                key: KEY,
                address: '杭州电子科技大学',
                city: '杭州',
                output: 'JSON'
            }
        });

        if (geoRes.data.status !== '1') {
            console.error('❌ 地理编码失败:', geoRes.data.info);
            return;
        }

        const location = geoRes.data.geocodes[0].location;
        console.log(`✅ 坐标: ${location}`);

        // Step 2: 搜索附近的KFC
        console.log('\n🔍 正在搜索附近KFC...');
        const poiRes = await axios.get('https://restapi.amap.com/v5/place/text', {
            params: {
                key: KEY,
                keywords: '肯德基',
                region: '杭州',
                page: 1,
                offset: 25
            }
        });

        if (poiRes.data.status !== '1') {
            console.error('❌ POI搜索失败:', poiRes.data.info);
            return;
        }

        const pois = poiRes.data.pois || [];
        console.log(`✅ 共找到 ${pois.length} 家肯德基`);

        // Step 3: 计算距离并排序
        const [myLng, myLat] = location.split(',').map(Number);

        function calcDistance(lng1, lat1, lng2, lat2) {
            const R = 6371000;
            const dLat = (lat2 - lat1) * Math.PI / 180;
            const dLng = (lng2 - lng1) * Math.PI / 180;
            const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
                      Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
                      Math.sin(dLng/2) * Math.sin(dLng/2);
            const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
            return R * c;
        }

        const withDist = pois.map(poi => {
            const [poiLng, poiLat] = poi.location.split(',').map(Number);
            const dist = calcDistance(myLng, myLat, poiLng, poiLat);
            return { ...poi, distance_m: Math.round(dist) };
        });

        withDist.sort((a, b) => a.distance_m - b.distance_m);

        // Step 4: 取最近的5家
        const top5 = withDist.slice(0, 5);

        console.log('\n' + '='.repeat(80));
        console.log('🏪 最近的5家肯德基：');
        console.log('='.repeat(80));

        top5.forEach((poi, i) => {
            const distKm = (poi.distance_m / 1000).toFixed(2);
            console.log(`\n${i+1}. ${poi.name}`);
            console.log(`   📍 地址: ${poi.address || '无'}`);
            console.log(`   📏 距离: ${distKm}公里`);
            console.log(`   🗺️  坐标: ${poi.location}`);
            console.log(`   📞 电话: ${poi.tel || '无'}`);
            console.log(`   🕐 营业时间: ${poi.business_area || '未知'}`);
        });

        // Step 5: 保存到桌面文件
        const resultContent = [
            '杭州电子科技大学附近最近的5家肯德基',
            '='.repeat(60),
            `查询时间: ${new Date().toLocaleString()}`,
            `中心坐标: ${location}`,
            '',
            ...top5.map((poi, i) => {
                const distKm = (poi.distance_m / 1000).toFixed(2);
                return [
                    `${i+1}. ${poi.name}`,
                    `   地址: ${poi.address || '无'}`,
                    `   距离: ${distKm}公里`,
                    `   坐标: ${poi.location}`,
                    `   电话: ${poi.tel || '无'}`,
                    ''
                ].join('\n');
            })
        ].join('\n');

        const desktopPath = 'C:\\Users\\11765\\Desktop';
        const fileName = '杭州电子科技大学附近KFC店信息.txt';
        const fullPath = path.join(desktopPath, fileName);
        fs.writeFileSync(fullPath, resultContent, 'utf8');
        console.log(`\n✅ 信息已保存到: ${fullPath}`);

        // Also save individual file  
        const kfcInfoJson = top5.map((poi, i) => ({
            id: i + 1,
            name: poi.name,
            address: poi.address || '无',
            distance_m: poi.distance_m,
            distance_km: (poi.distance_m / 1000).toFixed(2),
            location: poi.location,
            tel: poi.tel || '无',
            type: poi.type || '肯德基'
        }));

        const jsonPath = path.join(desktopPath, 'kfc_nearby_data.json');
        fs.writeFileSync(jsonPath, JSON.stringify(kfcInfoJson, null, 2), 'utf8');
        console.log(`✅ JSON数据已保存到: ${jsonPath}`);

        // Step 6: Create NEWKFC folder and save data there too
        const newkfcPath = path.join(desktopPath, 'NEWKFC');
        if (!fs.existsSync(newkfcPath)) {
            fs.mkdirSync(newkfcPath, { recursive: true });
        }

        const newkfcFilePath = path.join(newkfcPath, '附近KFC信息.txt');
        fs.writeFileSync(newkfcFilePath, resultContent, 'utf8');
        console.log(`✅ 已同步到: ${newkfcFilePath}`);

        // Step 7: 输出高德地图搜索链接
        console.log('\n🔗 高德地图搜索链接:');
        console.log(`https://ditu.amap.com/search?query=肯德基&query_type=RQBXY&longitude=${myLng}&latitude=${myLat}&range=5000`);

    } catch (err) {
        console.error('❌ 错误:', err.message);
    }
}

main();
